// ───────────────────────── auth ─────────────────────────
// Returns { mode:'oauth'|'apiKey', token, betas } and refreshes the OAuth token
// in place (read-modify-write, mode 0600) when near expiry. Falls back to the
// existing token on refresh failure.
async function resolveAuth() {
